    return [(ObservationKind.SIZE_BOUND, SizeBoundPayload(min=int(match.group("n")), max=None))]


def _max_length(match: re.Match[str]) -> list[Classification]:
    return [(ObservationKind.SIZE_BOUND, SizeBoundPayload(min=None, max=int(match.group("n"))))]


def _length_range(match: re.Match[str]) -> list[Classification]:
    return [
        (
            ObservationKind.SIZE_BOUND,
            SizeBoundPayload(min=int(match.group("min")), max=int(match.group("max"))),
